1	import { InvoiceListToolbar } from '../../slots/defs/invoiceListToolbar';
2	import { useSearchParam, asString } from '../../url/useSearchParam';
3	import { formatMoney } from '../../ui/money';
4	import { useInvoices, usePayInvoice, useSendInvoice } from './invoices';
5	
6	// A project's invoices and what they add up to. Reads its own query key (scoped to the project) and
7	// derives the total from the rows — the aggregate is never stored, so it always matches the list.
8	// Each row shows its lifecycle status and the control for its next step: Send while DRAFT, Mark paid
9	// while SENT (payment is only offered once an invoice has been sent), nothing once PAID. The ordering comes
10	// from the shared `invoiceSort` URL key (set by a toolbar control), so the server returns the rows
11	// already in order.
12	export function InvoiceList({ projectId }: { projectId: number }) {
13	  const [sort] = useSearchParam('invoiceSort', asString);
14	  const { data: invoices } = useInvoices(projectId, sort || undefined);
15	  const send = useSendInvoice(projectId);
16	  const pay = usePayInvoice(projectId);
17	
18	  if (!invoices) {
19	    return null;
20	  }
21	
22	  const total = invoices.reduce((sum, invoice) => sum + Number(invoice.amount), 0);
23	
24	  return (
25	    <>
26	    <InvoiceListToolbar.Slot projectId={projectId} />
27	    <table data-testid="project-invoices-table">
28	      <thead>
29	        <tr>
30	          <th>Amount</th>
31	          <th>Issued</th>
32	          <th>Due</th>
33	          <th>Status</th>
34	          <th></th>
35	        </tr>
36	      </thead>
37	      <tbody>
38	        {invoices.map((invoice) => (
39	          <tr key={invoice.id} data-testid={`invoice-row-${invoice.id}`}>
40	            <td data-testid="invoice-amount">{formatMoney(invoice.amount)}</td>
41	            <td data-testid="invoice-issued">{invoice.issuedDate}</td>
42	            <td data-testid="invoice-due">{invoice.dueDate}</td>
43	            <td data-testid="invoice-status">{invoice.status}</td>
44	            <td>
45	              {invoice.status === 'DRAFT' && (
46	                <button
47	                  type="button"
48	                  data-testid={`invoice-send-${invoice.id}`}
49	                  disabled={send.isPending}
50	                  onClick={() => send.mutate({ id: invoice.id })}
51	                >
52	                  Send
53	                </button>
54	              )}
55	              {invoice.status === 'SENT' && (
56	                <button
57	                  type="button"
58	                  data-testid={`invoice-pay-${invoice.id}`}
59	                  disabled={pay.isPending}
60	                  onClick={() => pay.mutate({ id: invoice.id })}
61	                >
62	                  Mark paid
63	                </button>
64	              )}
65	            </td>
66	          </tr>
67	        ))}
68	      </tbody>
69	      <tfoot>
70	        <tr>
71	          <td data-testid="project-invoices-total">{formatMoney(total)}</td>
72	        </tr>
73	      </tfoot>
74	    </table>
75	    </>
76	  );
77	}
